// Generated by tools/gen_h753_runs.py: edit RUNS there, not this file.

//! Run A: the TBS Lucid H7's UARTs at its rates, on its DMA streams,
//! under its clock tree, from HSE as the Lucid runs it (the other runs
//! use HSI). USART6 (CRSF) is on the Lucid's pins, PC6 and
//! PC7; USART1 (SBUS) and USART3 (MSP) are on pins the Zio headers carry.
//! USART2 is a control at 115200.
//!
//! First with the data cache off, the Lucid's policy: the full check
//! list on each UART, then all four streaming at once. Then with both
//! caches on: buffers in cached RAM and DTCM must be refused, and the
//! four must stream at once again.
//!
//! RTIC owns every interrupt; FerroHAL only enables each UART's and its
//! streams' own interrupt bits. Each UART is one shared resource, served by
//! its handlers and used by the `checks` task under RTIC's lock, one call at
//! a time (`tests::Locked`; `docs/design/uart-ownership.md`). Each vector in
//! use, and what serves it:
//!
//! | Vector | Serves | Priority |
//! | --- | --- | --- |
//! | `USART6`, `DMA1_STREAM0`, `DMA1_STREAM6` | USART6's `on_interrupt` | 2 |
//! | `USART1`, `DMA2_STREAM4`, `DMA2_STREAM5` | USART1's `on_interrupt` | 2 |
//! | `USART3`, `DMA1_STREAM1`, `DMA1_STREAM3` | USART3's `on_interrupt` | 2 |
//! | `USART2`, `DMA1_STREAM2`, `DMA1_STREAM4` | USART2's `on_interrupt` | 2 |
//! | `SPI1` | RTIC, dispatching the priority 1 `checks` task | 1 |

#![no_std]
#![no_main]

#[path = "../board.rs"]
mod board;
#[path = "../../../common/tests.rs"]
mod tests;

use defmt_rtt as _;
use panic_probe as _;

#[rtic::app(device = ferrohal_stm32::device, peripherals = true, dispatchers = [SPI1])]
mod app {
    use cortex_m::peripheral::{CPUID, SCB};
    use ferrohal_stm32::{
        chip::{Interrupt, check_dma_buffer},
        dma::BufferError,
        uart::{Config, Parity, StopBits, Uart, Vectors},
    };

    use crate::{
        board::{self, RX_RING, TX_BUFFER},
        tests::{self, Locked, Loop, Report},
    };

    /// The Lucid's frames: CRSF to the receiver, SBUS from the DJI
    /// connector (without the inversion FerroHAL cannot set yet), MSP to
    /// the DisplayPort.
    const CRSF: Config = Config::new(ferrohal_stm32::time::Hertz(420_000));
    const SBUS: Config = Config::new(ferrohal_stm32::time::Hertz(100_000))
        .with_parity(Parity::Even)
        .with_stop_bits(StopBits::Two);
    const MSP: Config = Config::new(ferrohal_stm32::time::Hertz(115_200));

    #[shared]
    struct Shared {
        usart6: Uart<board::Usart6Lucid>,
        usart1: Uart<board::Usart1Lucid>,
        usart3: Uart<board::Usart3Lucid>,
        usart2: Uart<board::Usart2Control>,
    }

    #[local]
    struct Local {
        vectors_usart6: Vectors,
        vectors_usart1: Vectors,
        vectors_usart3: Vectors,
        vectors_usart2: Vectors,
        led: board::Led,
        scb: SCB,
        cpuid: CPUID,
    }

    #[init]
    fn init(cx: init::Context) -> (Shared, Local) {
        let mut core = cx.core;
        // The cycle counter, for the wait-bound check.
        core.DCB.enable_trace();
        core.DWT.enable_cycle_counter();
        // The buffers' block is non-cacheable before anything could cache it.
        board::dma_region(&mut core);

        let mut run = match board::run_a(cx.device) {
            Ok(run) => run,
            Err(error) => defmt::panic!("clocks: {}", error),
        };
        // `freeze` must land on the tree worked out while compiling.
        defmt::assert_eq!(run.rcc.clocks(), board::CLOCKS);
        defmt::info!("run A, clocks: {}", board::CLOCKS);

        let mut buffers = board::dma_buffers().into_iter();
        let usart6 = board::open(
            &mut run.rcc,
            "USART6 PC6->PC7, CRSF 420000",
            run.usart6,
            &CRSF,
            buffers.next().unwrap(),
        );
        let usart1 = board::open(
            &mut run.rcc,
            "USART1 PB6->PB7, SBUS 100000 8E2",
            run.usart1,
            &SBUS,
            buffers.next().unwrap(),
        );
        let usart3 = board::open(
            &mut run.rcc,
            "USART3 PB10->PB11, MSP 115200",
            run.usart3,
            &MSP,
            buffers.next().unwrap(),
        );
        let usart2 = board::open(
            &mut run.rcc,
            "USART2 PD5->PD6, control",
            run.usart2,
            &MSP,
            buffers.next().unwrap(),
        );

        let vectors_usart6 = usart6.vectors();
        let vectors_usart1 = usart1.vectors();
        let vectors_usart3 = usart3.vectors();
        let vectors_usart2 = usart2.vectors();
        checks::spawn().ok();
        (
            Shared {
                usart6,
                usart1,
                usart3,
                usart2,
            },
            Local {
                vectors_usart6,
                vectors_usart1,
                vectors_usart3,
                vectors_usart2,
                led: run.led,
                scb: core.SCB,
                cpuid: core.CPUID,
            },
        )
    }

    #[task(binds = USART6, priority = 2, shared = [usart6])]
    fn usart6_line(mut cx: usart6_line::Context) {
        cx.shared.usart6.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA1_STREAM0, priority = 2, shared = [usart6])]
    fn usart6_rx(mut cx: usart6_rx::Context) {
        cx.shared.usart6.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA1_STREAM6, priority = 2, shared = [usart6])]
    fn usart6_tx(mut cx: usart6_tx::Context) {
        cx.shared.usart6.lock(|uart| tests::serve(uart));
    }

    #[task(binds = USART1, priority = 2, shared = [usart1])]
    fn usart1_line(mut cx: usart1_line::Context) {
        cx.shared.usart1.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA2_STREAM4, priority = 2, shared = [usart1])]
    fn usart1_rx(mut cx: usart1_rx::Context) {
        cx.shared.usart1.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA2_STREAM5, priority = 2, shared = [usart1])]
    fn usart1_tx(mut cx: usart1_tx::Context) {
        cx.shared.usart1.lock(|uart| tests::serve(uart));
    }

    #[task(binds = USART3, priority = 2, shared = [usart3])]
    fn usart3_line(mut cx: usart3_line::Context) {
        cx.shared.usart3.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA1_STREAM1, priority = 2, shared = [usart3])]
    fn usart3_rx(mut cx: usart3_rx::Context) {
        cx.shared.usart3.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA1_STREAM3, priority = 2, shared = [usart3])]
    fn usart3_tx(mut cx: usart3_tx::Context) {
        cx.shared.usart3.lock(|uart| tests::serve(uart));
    }

    #[task(binds = USART2, priority = 2, shared = [usart2])]
    fn usart2_line(mut cx: usart2_line::Context) {
        cx.shared.usart2.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA1_STREAM2, priority = 2, shared = [usart2])]
    fn usart2_rx(mut cx: usart2_rx::Context) {
        cx.shared.usart2.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA1_STREAM4, priority = 2, shared = [usart2])]
    fn usart2_tx(mut cx: usart2_tx::Context) {
        cx.shared.usart2.lock(|uart| tests::serve(uart));
    }

    #[task(priority = 1, shared = [usart6, usart1, usart3, usart2], local = [vectors_usart6, vectors_usart1, vectors_usart3, vectors_usart2, led, scb, cpuid])]
    async fn checks(cx: checks::Context) {
        tests::set_cpu_hz(board::CLOCKS.cpu.0);
        let mut report = Report::new();
        report.check_for(
            "USART6 PC6->PC7, CRSF 420000",
            "UART-003 RESOURCE-001",
            "vectors enabled",
            tests::vectors_verified(cx.local.vectors_usart6),
        );
        report.check_for(
            "USART1 PB6->PB7, SBUS 100000 8E2",
            "UART-003 RESOURCE-001",
            "vectors enabled",
            tests::vectors_verified(cx.local.vectors_usart1),
        );
        report.check_for(
            "USART3 PB10->PB11, MSP 115200",
            "UART-003 RESOURCE-001",
            "vectors enabled",
            tests::vectors_verified(cx.local.vectors_usart3),
        );
        report.check_for(
            "USART2 PD5->PD6, control",
            "UART-003 RESOURCE-001",
            "vectors enabled",
            tests::vectors_verified(cx.local.vectors_usart2),
        );
        let mut usart6 = Locked(cx.shared.usart6);
        let mut usart1 = Locked(cx.shared.usart1);
        let mut usart3 = Locked(cx.shared.usart3);
        let mut usart2 = Locked(cx.shared.usart2);

        tests::full_suite(
            &mut report,
            &mut Loop {
                name: "USART6 PC6->PC7, CRSF 420000",
                uart: &mut usart6,
            },
            &CRSF,
            RX_RING,
            TX_BUFFER,
            &mut tests::nvic_mask(Interrupt::DMA1_STREAM0),
            &mut tests::nvic_mask_all([
                Interrupt::USART6,
                Interrupt::DMA1_STREAM0,
                Interrupt::DMA1_STREAM6,
            ]),
            true,
        );
        tests::full_suite(
            &mut report,
            &mut Loop {
                name: "USART1 PB6->PB7, SBUS 100000 8E2",
                uart: &mut usart1,
            },
            &SBUS,
            RX_RING,
            TX_BUFFER,
            &mut tests::nvic_mask(Interrupt::DMA2_STREAM4),
            &mut tests::nvic_mask_all([
                Interrupt::USART1,
                Interrupt::DMA2_STREAM4,
                Interrupt::DMA2_STREAM5,
            ]),
            true,
        );
        report.check_for(
            "USART1 PB6->PB7, SBUS 100000 8E2",
            "UART-020",
            "a masked line keeps its events out until unmasking",
            tests::line_mask(&mut Loop {
                name: "USART1 PB6->PB7, SBUS 100000 8E2",
                uart: &mut usart1,
            }),
        );
        tests::full_suite(
            &mut report,
            &mut Loop {
                name: "USART3 PB10->PB11, MSP 115200",
                uart: &mut usart3,
            },
            &MSP,
            RX_RING,
            TX_BUFFER,
            &mut tests::nvic_mask(Interrupt::DMA1_STREAM1),
            &mut tests::nvic_mask_all([
                Interrupt::USART3,
                Interrupt::DMA1_STREAM1,
                Interrupt::DMA1_STREAM3,
            ]),
            true,
        );
        tests::full_suite(
            &mut report,
            &mut Loop {
                name: "USART2 PD5->PD6, control",
                uart: &mut usart2,
            },
            &MSP,
            RX_RING,
            TX_BUFFER,
            &mut tests::nvic_mask(Interrupt::DMA1_STREAM2),
            &mut tests::nvic_mask_all([
                Interrupt::USART2,
                Interrupt::DMA1_STREAM2,
                Interrupt::DMA1_STREAM4,
            ]),
            true,
        );

        report.check_for(
            "USART6 + USART1 + USART3 + USART2",
            "UART-002",
            "8 KiB each, all at once",
            tests::streams(
                &mut [
                    &mut Loop {
                        name: "USART6 PC6->PC7, CRSF 420000",
                        uart: &mut usart6,
                    },
                    &mut Loop {
                        name: "USART1 PB6->PB7, SBUS 100000 8E2",
                        uart: &mut usart1,
                    },
                    &mut Loop {
                        name: "USART3 PB10->PB11, MSP 115200",
                        uart: &mut usart3,
                    },
                    &mut Loop {
                        name: "USART2 PD5->PD6, control",
                        uart: &mut usart2,
                    },
                ],
                8 * 1024,
            ),
        );

        // The same load with both caches on.
        board::caches_on(cx.local.scb, cx.local.cpuid);
        defmt::info!(
            "I-cache {=bool}, D-cache {=bool}",
            SCB::icache_enabled(),
            SCB::dcache_enabled()
        );
        // The stack is ordinary, cached AXI SRAM.
        let cached = core::hint::black_box([0u8; 32]);
        report.check_for(
            "D-cache on",
            "GLUE-003",
            "buffer in cached RAM refused",
            tests::expect_refusal(check_dma_buffer(&cached), BufferError::Cacheable),
        );
        // SAFETY: never read; only its address is checked.
        let dtcm = unsafe { core::slice::from_raw_parts(0x2000_0000 as *const u8, 32) };
        report.check_for(
            "D-cache on",
            "GLUE-003",
            "buffer in DTCM refused",
            tests::expect_refusal(check_dma_buffer(dtcm), BufferError::Unreachable),
        );
        report.check_for(
            "USART6 + USART1 + USART3 + USART2",
            "UART-002",
            "8 KiB each, all at once, caches on",
            tests::streams(
                &mut [
                    &mut Loop {
                        name: "USART6 PC6->PC7, CRSF 420000",
                        uart: &mut usart6,
                    },
                    &mut Loop {
                        name: "USART1 PB6->PB7, SBUS 100000 8E2",
                        uart: &mut usart1,
                    },
                    &mut Loop {
                        name: "USART3 PB10->PB11, MSP 115200",
                        uart: &mut usart3,
                    },
                    &mut Loop {
                        name: "USART2 PD5->PD6, control",
                        uart: &mut usart2,
                    },
                ],
                8 * 1024,
            ),
        );
        report.check_for(
            "USART6 PC6->PC7, CRSF 420000",
            "UART-006 WAIT-001",
            "counted and clocked waits within their bounds, caches on",
            tests::wait_bounds(
                &mut Loop {
                    name: "USART6 PC6->PC7, CRSF 420000",
                    uart: &mut usart6,
                },
                board::CLOCKS.cpu.0,
                CRSF.baudrate.0,
            ),
        );
        report.check_for(
            "USART1 PB6->PB7, SBUS 100000 8E2",
            "UART-006 WAIT-001",
            "counted and clocked waits within their bounds, caches on",
            tests::wait_bounds(
                &mut Loop {
                    name: "USART1 PB6->PB7, SBUS 100000 8E2",
                    uart: &mut usart1,
                },
                board::CLOCKS.cpu.0,
                SBUS.baudrate.0,
            ),
        );
        report.check_for(
            "USART3 PB10->PB11, MSP 115200",
            "UART-006 WAIT-001",
            "counted and clocked waits within their bounds, caches on",
            tests::wait_bounds(
                &mut Loop {
                    name: "USART3 PB10->PB11, MSP 115200",
                    uart: &mut usart3,
                },
                board::CLOCKS.cpu.0,
                MSP.baudrate.0,
            ),
        );
        report.check_for(
            "USART2 PD5->PD6, control",
            "UART-006 WAIT-001",
            "counted and clocked waits within their bounds, caches on",
            tests::wait_bounds(
                &mut Loop {
                    name: "USART2 PD5->PD6, control",
                    uart: &mut usart2,
                },
                board::CLOCKS.cpu.0,
                MSP.baudrate.0,
            ),
        );

        report.check_for(
            "USART6 + USART1 + USART3 + USART2",
            "RESOURCE-002",
            "every handler serves its UART through Service",
            tests::served(),
        );
        let led = cx.local.led;
        tests::finish(&report, || led.set_high());
    }
}
